// === Tab: mySketch ===
// by SamuelYAN
// more works //
// https://twitter.com/SamuelAnn0924
// https://www.instagram.com/samuel_yan_1990/

// Black Field : Point · Line · Plane
// minimal black & white universe
// based on original structure, refined for exhibition use

let seed;
let mySize;
let rez = 0.12;
let t = 0;

function setup() {
  seed = floor(random(999999));
  randomSeed(seed);
  noiseSeed(seed);

  mySize = max(windowWidth, windowHeight);
  createCanvas(mySize, mySize, WEBGL);
  frameRate(30);
  background(0);

}

function draw() {
  background(0);
  randomSeed(seed);

  t += 0.01; // slow breathing time

  let pulse = sin(t) * 0.5 + 0.5;

  push();
  translate(0, 0, -mySize * 0.15);

  let cubeSize = mySize * 0.6;
  let step = cubeSize / 6;

  // compress depth → universe slice
  for (let x = -cubeSize / 2; x <= cubeSize / 2; x += step) {
    for (let y = -cubeSize / 2; y <= cubeSize / 2; y += step) {
      for (let z = -cubeSize / 2; z <= cubeSize / 2; z += step * 1) {

        let n = noise(x * rez, y * rez, z * rez + t);

        let d = dist(x, y, z, 0, 0, 0);
        let field = constrain(1 - d / (mySize * 0.5), 0, 1);

        let energy =
          (n * 0.6 + field * 0.4) *
          map(pulse, 0, 1, 0.85, 1.15);

        if (energy < 0.2) continue; // strong minimalism

        push();
        translate(x, y, z);

        let rot = energy * TAU * 0.15;
        rotateX(rot);
        rotateY(rot * 0.6);
        rotateZ(rot * 0.6+t);

        if (energy < 0.35) {
          drawBWPoint(energy);
        } else if (energy < 0.65) {
          drawBWLine(energy);
        } else {
          drawBWPlane(energy);
        }

        pop();
      }
    }
  }

  pop();
}

// ---------- Point ----------
function drawBWPoint(e) {
  let r = mySize * 0.01 * e;
  noStroke();
  fill(255);
  sphere(r, 32, 32);
}

// ---------- Line ----------
function drawBWLine(e) {
  let len = mySize * 0.0125 * e;
  let num = int(map(e, 0.35, 0.65, 1, 2));

  stroke(255);
  strokeWeight(0.5 + e);

  for (let i = 0; i < num; i++) {
    push();
    rotateY(i * TAU / num);
    rotateX(sin(t + i) * 1.2/2.0);
    line(0, -len, 0, 0, len, 0);
    pop();
  }
}

// ---------- Plane ----------
function drawBWPlane(e) {
  let s = mySize * 0.25 * e;

  noStroke();
  fill(255,random(50,100));
  // strokeWeight(1);

  push();
  rotateX(HALF_PI * int(random(4)));
  rotateY(HALF_PI * int(random(4)));
  // rotateZ(HALF_PI * int(random(4)));
  plane(s, s);
  pop();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  mySize = max(windowWidth, windowHeight);
}

